"""Shared look of the home panels (direction B, 2026-11-22). Copied from xiyue-service-work/panel-base; edit there, then sync."""

PB_CSS = '/* 面板底座 v1 · 方向 B「仪表台」（2026-11-22 选定）\n   源文件：C:\\projects\\xiyue-service-work\\panel-base\\panel-base.css —— 各面板各自拷一份，改这里再同步过去。\n   只管四样：颜色变量、字体与字号阶梯、圆角间距、回总入口的顶栏（.pb-hub）。各面板把自己的变量名映射到 --pb-*。\n   颜色只表示含义：accent=可点/进行中，warn=在等/要注意，ok=好转/完成，bad=出错/变差；\n   行情涨跌另用 mkt-up(红)/mkt-down(绿)，和好坏分开。 */\n:root{\n  --pb-bg:#F3F4F5;--pb-panel:#FFFFFF;--pb-field:#FFFFFF;--pb-hover:#EEF0F2;\n  --pb-ink:#16191D;--pb-muted:#5B636E;--pb-line:#DFE2E6;\n  --pb-accent:#1F6FEB;--pb-accent-ink:#FFFFFF;--pb-accent-soft:#E8F0FE;\n  --pb-warn:#B35900;--pb-ok:#1A7F37;--pb-bad:#C62828;\n  --pb-mkt-up:#D1242F;--pb-mkt-down:#1A7F37;\n  --pb-hub-bg:#16191D;--pb-hub-ink:#E9ECEF;--pb-hub-on:#2B3138;\n  --pb-font:system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;\n  --pb-mono:ui-monospace,"Cascadia Mono","JetBrains Mono",Consolas,"SF Mono",Menlo,monospace;\n  --pb-fs-xs:12px;--pb-fs-sm:13px;--pb-fs:14px;--pb-fs-md:16px;--pb-fs-lg:20px;--pb-fs-xl:28px;\n  --pb-r:6px;--pb-r-lg:8px;--pb-gap:16px;\n}\n@media (prefers-color-scheme:dark){:root{\n  --pb-bg:#111315;--pb-panel:#1A1D21;--pb-field:#14171A;--pb-hover:#23272C;\n  --pb-ink:#E6E9EC;--pb-muted:#9AA3AE;--pb-line:#2D3238;\n  --pb-accent:#4C8DFF;--pb-accent-ink:#0B1220;--pb-accent-soft:#1A2740;\n  --pb-warn:#E8A15A;--pb-ok:#5BC27A;--pb-bad:#F07070;\n  --pb-mkt-up:#F26B6B;--pb-mkt-down:#4CC07A;\n  --pb-hub-bg:#0B0D0F;--pb-hub-ink:#E6E9EC;--pb-hub-on:#23272C;\n}}\n.pb-hub{position:sticky;top:0;z-index:1000;display:flex;flex-wrap:nowrap;margin:0;border:0;align-items:center;gap:2px;height:40px;padding:0 16px;\n  background:var(--pb-hub-bg);color:var(--pb-hub-ink);font:400 var(--pb-fs) var(--pb-font);overflow-x:auto;scrollbar-width:none}\n.pb-hub::-webkit-scrollbar{display:none}\n.pb-hub b{font-weight:600;margin-right:12px;white-space:nowrap}\n.pb-hub a{color:inherit!important;text-decoration:none!important;border:0!important;padding:5px 10px;border-radius:var(--pb-r);opacity:.7;white-space:nowrap}\n.pb-hub a:hover{opacity:1;background:var(--pb-hub-on)}\n.pb-hub a[aria-current]{opacity:1;background:var(--pb-hub-on);font-weight:600}\n.pb-hub a:focus-visible{outline:2px solid var(--pb-accent);outline-offset:1px}\n.pb-num{font-family:var(--pb-mono);font-variant-numeric:tabular-nums}\n@media (max-width:480px){.pb-hub{padding:0 4px}.pb-hub b{display:none}.pb-hub a{padding:5px 6px}}\n'

HUB = '<nav class="pb-hub" aria-label="家里的面板"><b>家里的面板</b><a href="/app/piweb/chat" data-k="chat">溪月</a><a href="/app/piweb/manage" data-k="manage">管理</a><a href="/app/workbench/" data-k="workbench">工作台</a><a href="/app/nutrition/" data-k="nutrition">家庭健康</a><a href="/app/stock/" data-k="stock">涨停</a><a href="http://192.168.5.198:18890/" target="_blank" rel="noopener" data-k="proxy">旁路代理</a></nav>'


def hub(active: str) -> str:
    """The bar back to the other panels, with this one marked."""
    return HUB.replace(f'data-k="{active}"', f'data-k="{active}" aria-current="page"', 1)
